const products=await fetch('/products.json').then(r=>r.json());const byId=Object.fromEntries(products.map(p=>[p.id,p]));const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('fr-DZ').format(n)+' DA';const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let cart={};try{cart=JSON.parse(localStorage.getItem('bluedelta-cart')||'{}');if(!cart||typeof cart!=='object'||Array.isArray(cart))cart={};for(const id of Object.keys(cart))if(!byId[id]||!Number.isInteger(cart[id])||cart[id]<1||cart[id]>99)delete cart[id]}catch{cart={}}const entries=()=>Object.entries(cart).map(([id,qty])=>({...byId[id],qty}));const total=()=>entries().reduce((s,p)=>s+p.price*p.qty,0);let toastTimer;
function toast(text){$('.toast').textContent=text;$('.toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2800)}
function save(){try{localStorage.setItem('bluedelta-cart',JSON.stringify(cart))}catch{toast('Votre navigateur ne permet pas de conserver le panier.')}document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=Object.values(cart).reduce((a,b)=>a+b,0));renderCart();renderSummary()}
function add(id,qty=1){if(!byId[id]||!Number.isInteger(qty)||qty<1||qty>99)throw new Error('Produit ou quantité invalide');cart[id]=Math.min(99,(cart[id]||0)+qty);save();toast(byId[id].name+' ajouté au panier')}
document.addEventListener('click',e=>{const a=e.target.closest('[data-add]');if(a){let qty=a.hasAttribute('data-detail')?Number($('#product-quantity').value):1;if(!Number.isInteger(qty)||qty<1||qty>99){toast('Choisissez une quantité entre 1 et 99.');return}add(a.dataset.add,qty)}const step=e.target.closest('[data-qty-step]');if(step){const input=$('#product-quantity');input.value=Math.max(1,Math.min(99,(Number(input.value)||1)+Number(step.dataset.qtyStep)))}const c=e.target.closest('[data-cart-step]');if(c){cart[c.dataset.id]=Math.max(1,Math.min(99,cart[c.dataset.id]+Number(c.dataset.cartStep)));save()}const r=e.target.closest('[data-remove]');if(r){delete cart[r.dataset.remove];save();toast('Produit retiré du panier')}});
$('.menu-toggle')?.addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open);$('.menu-toggle').setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}});document.querySelectorAll('.navlinks a').forEach(a=>{if(a.pathname===location.pathname)a.classList.add('active')});
let filter=new URLSearchParams(location.search).get('categorie')||'all';if(!['all','auto','industrie'].includes(filter))filter='all';function filterProducts(){const q=($('#product-search')?.value||'').toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'');let n=0;document.querySelectorAll('#catalog-grid .product-card').forEach(el=>{const name=el.dataset.name.normalize('NFD').replace(/\p{Diacritic}/gu,'');const visible=(filter==='all'||el.dataset.cat===filter)&&name.includes(q);el.hidden=!visible;if(visible)n++});if($('#result-count'))$('#result-count').textContent=n+' produit'+(n>1?'s':'');if($('#no-results'))$('#no-results').hidden=n>0;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)})}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;history.replaceState(null,'',filter==='all'?'/produits/':'?categorie='+filter);filterProducts()}));$('#product-search')?.addEventListener('input',filterProducts);$('#reset-search')?.addEventListener('click',()=>{filter='all';$('#product-search').value='';filterProducts()});filterProducts();
function renderCart(){const el=$('#cart-page');if(!el)return;if(!entries().length){el.innerHTML='<div class="empty"><h2>Votre panier est vide</h2><p>Découvrez nos gammes et ajoutez les produits adaptés à votre besoin.</p><a class="btn" href="/produits/">Découvrir les produits</a></div>';return}el.innerHTML=entries().map(p=>`<article class="cart-row"><a href="/produits/${p.id}/"><img src="/assets/${p.image}" alt="${p.name}"></a><div><h3><a href="/produits/${p.id}/">${p.name}</a></h3><p>${p.format} · ${money(p.price)} / unité</p><button class="remove" data-remove="${p.id}">Retirer</button></div><div class="quantity"><button data-cart-step="-1" data-id="${p.id}" aria-label="Réduire ${p.name}">−</button><input aria-label="Quantité de ${p.name}" type="number" min="1" max="99" value="${p.qty}" data-cart-input="${p.id}"><button data-cart-step="1" data-id="${p.id}" aria-label="Augmenter ${p.name}">+</button></div><span class="price">${money(p.qty*p.price)}</span></article>`).join('')+`<div class="cart-total"><div class="summary-line"><span>Livraison</span><span>À confirmer</span></div><div class="summary-line total"><span>Total produits</span><span>${money(total())}</span></div><a href="/commande/" class="btn full">Passer la commande</a><p class="fine">Aucun paiement prélevé en ligne. Confirmation avec BLUE DELTA.</p><a href="/produits/" class="textlink">Continuer mes achats</a></div>`;el.querySelectorAll('[data-cart-input]').forEach(input=>input.addEventListener('change',()=>{const n=Number(input.value);if(Number.isInteger(n)&&n>=1&&n<=99){cart[input.dataset.cartInput]=n;save()}else{toast('Quantité entre 1 et 99.');renderCart()}}))}
function renderSummary(){const el=$('#order-summary');if(!el)return;el.innerHTML='<h2>Votre commande</h2>'+entries().map(p=>`<div class="summary-line"><span>${p.name}<br><small>${p.format} × ${p.qty}</small></span><strong>${money(p.price*p.qty)}</strong></div>`).join('')+`<div class="summary-line"><span>Livraison</span><span>À confirmer</span></div><div class="summary-line total"><span>Total produits</span><span>${money(total())}</span></div><a href="/panier/" class="textlink">Modifier mon panier</a>`}save();
if($('#wilaya')){try{const locations=await fetch('/locations.json').then(r=>{if(!r.ok)throw Error();return r.json()});$('#wilaya').innerHTML='<option value="">Choisir une wilaya</option>'+locations.map(w=>`<option value="${w.code}">${w.code} — ${escape(w.name)}</option>`).join('');$('#wilaya').addEventListener('change',()=>{const w=locations.find(w=>w.code==$('#wilaya').value);$('#commune').innerHTML='<option value="">Choisir une commune</option>'+(w?w.communes.map(c=>`<option>${escape(c)}</option>`).join(''):'');$('#commune').disabled=!w})}catch{$('#wilaya').outerHTML='<input id="wilaya" name="wilaya" required placeholder="Votre wilaya">';$('#commune').outerHTML='<input id="commune" name="commune" required placeholder="Votre commune">'}}
function messageLinks(text){return `<div class="buttons"><a class="btn" href="https://wa.me/213770866417?text=${encodeURIComponent(text)}" target="_blank" rel="noopener">Envoyer sur WhatsApp</a><a class="btn outline" href="mailto:contact@bluedelta.dz?subject=${encodeURIComponent('Demande BLUE DELTA')}&body=${encodeURIComponent(text)}">Envoyer par e-mail</a><button class="btn outline" type="button" id="copy-message">Copier le message</button></div><p class="fine">Votre demande sera transmise lorsque vous enverrez le message dans WhatsApp ou votre messagerie.</p>`}
function wireCopy(text){$('#copy-message')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);toast('Message copié')}catch{toast('Copie indisponible. Utilisez WhatsApp ou votre messagerie.')}})}
$('#checkout-form')?.addEventListener('submit',e=>{e.preventDefault();if(!entries().length){toast('Votre panier est vide.');return}const f=new FormData(e.target);const w=$('#wilaya');const wilaya=w.tagName==='SELECT'?w.selectedOptions[0].textContent:w.value;const lines=entries().map(p=>`${p.name} (${p.format}) × ${p.qty} : ${money(p.price*p.qty)}`);const text=`Bonjour BLUE DELTA, je souhaite commander :\n\n${lines.join('\n')}\n\nTotal produits : ${money(total())}\nLivraison et modalités de paiement à confirmer.\n\nNom : ${f.get('name')}\nTéléphone : ${f.get('phone')}\nEntreprise : ${f.get('company')||'—'}\nE-mail : ${f.get('email')||'—'}\nWilaya : ${wilaya}\nCommune : ${f.get('commune')}\nAdresse : ${f.get('address')}\nNote : ${f.get('message')||'—'}`;const result=$('#checkout-result');result.innerHTML=`<h3>Votre commande est prête à envoyer</h3><p>Vérifiez vos coordonnées et envoyez le récapitulatif à BLUE DELTA pour confirmation.</p><div class="info-box">${escape(f.get('name'))}<br>${escape(f.get('phone'))}<br>${escape(f.get('address'))}, ${escape(f.get('commune'))}, ${escape(wilaya)}<br><strong>Total produits : ${money(total())}</strong></div>${messageLinks(text)}`;result.hidden=false;wireCopy(text);result.scrollIntoView({behavior:'smooth',block:'center'})});
if($('#checkout-page')&&!entries().length){$('#checkout-page').innerHTML='<div class="empty"><h2>Votre panier est vide</h2><p>Ajoutez un produit avant de préparer votre commande.</p><a href="/produits/" class="btn">Voir les produits</a></div>'}
const params=new URLSearchParams(location.search);if($('#contact-form')){const p=byId[params.get('produit')];if(p)$('#contact-form textarea').value='Bonjour, je souhaite des informations sur '+p.name+' ('+p.format+').';if(params.get('objet')==='fiche-technique')$('#contact-form select').value='Fiche technique / FDS';$('#contact-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const text=`Bonjour BLUE DELTA,\n${f.get('subject')}\n\n${f.get('message')}\n\nNom : ${f.get('name')}\nTéléphone : ${f.get('phone')}\nEntreprise : ${f.get('company')||'—'}\nE-mail : ${f.get('email')||'—'}`;$('#contact-result').innerHTML='<h3>Votre demande est prête</h3>'+messageLinks(text);$('#contact-result').hidden=false;wireCopy(text);$('#contact-result').scrollIntoView({behavior:'smooth',block:'center'})})}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_bluedelta_products',description:'Rechercher dans le catalogue BLUE DELTA et lire les prix en DA.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(typeof input?.query!=='string')throw Error('query doit être du texte');return products.filter(p=>(p.name+' '+p.subtitle).toLowerCase().includes(input.query.toLowerCase())).map(p=>({id:p.id,name:p.name,price:p.price,currency:'DZD',url:'/produits/'+p.id+'/'}))}})).catch(()=>{})}catch{}}
